#!/usr/bin/env bash
# Checks for the public site (v2, built from the design canvas). From the repo root: bash tests/site.test.sh
# Scout's section left the home page by Josh's decision (2026-10-28), so its old checks are gone with it.
set -u
pass=0; fail=0
ok()  { echo "PASS $1"; pass=$((pass+1)); }
bad() { echo "FAIL $1"; fail=$((fail+1)); }
chk() { if eval "$2"; then ok "$1"; else bad "$1"; fi; }
PAGES="index.html services.html pricing.html about.html contact.html privacy.html"
for F in $PAGES; do
  chk "$F exists"                        "[[ -f $F ]]"
  chk "$F has viewport for phones"       "grep -q 'name=\"viewport\"' $F"
  chk "$F has a title"                   "grep -q '<title>.*Spring Cleaning Crew' $F"
  chk "$F has no bracketed placeholders" "! grep -qE '\\[[^]]{1,60}\\]' $F"
  chk "$F has no scripts or trackers (structured data only, Josh 2026-11-06)" "! grep -oi '<script[^>]*>' $F | grep -qvx '<script type=\"application/ld+json\">'"
  chk "$F has no design-tool leftovers"  "! grep -qE '\\{\\{|dc\\.html|support\\.js|<x-dc|<helmet' $F"
  chk "$F makes no unproven claims"      "! grep -qiE 'licensed|insured|same[- ]day|5 stars|[0-9.]+/5|reviews from' $F"
  chk "$F offers a free estimate"        "grep -qi 'free estimate' $F"
  chk "$F menu links every main page"    "for P in services pricing about contact; do grep -q \"href=\\\"\$P.html\\\"\" $F || exit 1; done"
  chk "$F footer links home and privacy" "grep -q 'href=\"index.html\"' $F && grep -q 'href=\"privacy.html\"' $F"
  chk "$F marks itself as the current page" "[[ $F == index.html ]] || grep -q \"href=\\\"$F\\\" class=\\\"on\\\" aria-current=\\\"page\\\"\" $F"
  chk "$F shows the business email"      "grep -q 'mailto:quotes@thespringcleaningcrew.com' $F"
  chk "$F has its own description"       "grep -q '<meta name=\"description\"' $F"
done
chk "every page has a different description" "[[ \$(grep -h '<meta name=\"description\"' $PAGES | sort -u | wc -l) -eq \$(echo $PAGES | wc -w) ]]"
chk "pages are built from src/ (no hand edits)" "python3 -I src/build.py --check"
chk "about page tells Josh's story"      "grep -q 'appreciate your business' about.html && grep -q \"Hey, I'm Josh\" about.html"
chk "privacy page says no cookies or tracking" "grep -qi 'no cookies' privacy.html && ! grep -qi '<script' privacy.html"
chk "sitemap lists every page"           "for P in $PAGES; do grep -q \"thespringcleaningcrew.com/\${P/index.html/}<\" sitemap.xml || exit 1; done"
chk "robots.txt points to the sitemap"   "grep -qx 'Sitemap: https://thespringcleaningcrew.com/sitemap.xml' robots.txt"
chk "every image a page uses is in the repo" "for s in \$(grep -ho 'src=\"[^\"]*\"' $PAGES | sed 's/src=\"//;s/\"//' | sort -u); do [[ -s \$s ]] || exit 1; done"
chk "every image has a real description"  "! grep -hoE '<img [^>]*>' $PAGES | grep -vqE 'alt=\"[^\"]{20,}\"'"
chk "illustrations are labeled as illustrations, not job photos" "! grep -hoE '<img [^>]*images/[^>]*>' $PAGES | grep -vq 'alt=\"Illustration: '"
chk "each image is under 150 KB"         "for f in badge.webp images/*.webp; do [[ \$(wc -c < \$f) -lt 150000 ]] || exit 1; done"
chk "garage before/after pair is on the clear-outs service" "grep -A4 'id=\"clear-outs\"' services.html | grep -q 'images/garage-before.webp' && grep -A6 'id=\"clear-outs\"' services.html | grep -q 'images/garage-after.webp'"
chk "realistic before/after carries a visible Illustration label" "grep -A8 'id=\"clear-outs\"' services.html | grep -qE '<figcaption[^>]*>Illustration'"
chk "only illustrations Josh kept are used (no haul, sell, clearout drawings)" "! grep -qE 'images/(haul|sell|clearout)\\.webp' $PAGES && [[ ! -e images/haul.webp && ! -e images/sell.webp && ! -e images/clearout.webp ]]"
chk "contact email present"              "grep -q 'mailto:quotes@thespringcleaningcrew.com' index.html"
chk "personal Gmail no longer shown"     "! grep -q 'thespringcleaningcrew@gmail.com' $PAGES"
chk "texting offered only with a real number" "! grep -qiE 'text (us|or|me)|text:|by text|texting' index.html || grep -qE 'href=\"(tel|sms):\\+?[0-9]' index.html"
chk "home links to pricing"              "grep -q 'href=\"pricing.html\"' index.html"
chk "badge image the home page uses is in the repo" "grep -q 'src=\"badge.webp\"' index.html && [[ -s badge.webp ]]"
chk "badge has a text description"       "grep -qE 'class=\"badge\"[^>]* alt=\"[^\"]{20,}\"' index.html"
chk "pricing links back home"            "grep -q 'href=\"index.html' pricing.html"
chk "Scout is not on the home page"      "! grep -qi 'scout' index.html"
chk "receipt promised only for Goodwill runs (Goodwill confirmed; Josh put it back 2026-11-06, superseding the earlier removal)" "[[ \$(grep -li 'receipt' $PAGES | tr '\n' ' ') == 'services.html ' ]] && grep -A4 'id=\"goodwill\"' services.html | grep -qi 'receipt in your name'"
chk "curbside heavy-trash-day carry-out is offered (311 confirmed, Josh 2026-11-06)" "grep -q 'id=\"curbside\"' services.html && grep -A4 'id=\"curbside\"' services.html | grep -qi 'heavy-trash'"
chk "no unconfirmed placeholders left on any page" "! grep -qE '\\[(CONFIRM|YOUR PRICE)' $PAGES"
chk "photo gets an estimate, the firm quote comes in person" "grep -q 'firm quote' index.html && ! grep -qi 'straight price' index.html"
chk "service area names The Woodlands where the area is stated (Josh, 2026-11-06)" "grep -q 'The Woodlands' contact.html && grep -q 'The Woodlands' about.html && grep -q 'The Woodlands' index.html"
chk "home and services descriptions name both areas" "grep '<meta name=\"description\"' index.html | grep -q 'The Woodlands' && grep '<meta name=\"description\"' services.html | grep -q 'The Woodlands'"
chk "service area: Waller, Sugar Land, Pearland, Crosby and The Woodlands on contact, about, llms.txt and the JSON-LD (Josh, 2026-11-07)" "for t in Waller 'Sugar Land' Pearland Crosby 'The Woodlands'; do grep -o '<h2>Where we work</h2><p>[^<]*' contact.html | grep -qF \"\$t\" && grep -o '<strong>Local.</strong>[^<]*' about.html | grep -qF \"\$t\" && grep '^- Service area:' llms.txt | grep -qF \"\$t\" && grep -q \"name.: .\$t\" index.html || { echo \"missing \$t\"; exit 1; }; done"
chk "services and pricing titles say Houston (SEO audit 2026-11-06)" "grep -q '<title>[^<]*Houston' services.html && grep -q '<title>[^<]*Houston' pricing.html"
chk "llms.txt: AI summary exists with the site's phone and email" "[[ -s llms.txt ]] && head -1 llms.txt | grep -qx '# The Spring Cleaning Crew' && grep -q '(832) 476-1941' llms.txt && grep -q 'quotes@thespringcleaningcrew.com' llms.txt"
chk "llms.txt: every price it states is on the live pages" "for p in \$(grep -oE '\\\$[0-9]+' llms.txt | sort -u); do grep -qF \"\$p\" pricing.html services.html || { echo \"missing \$p\"; exit 1; }; done"
chk "llms.txt: every service link points at a real anchor" "for a in \$(grep -oE 'services.html#[a-z-]+' llms.txt | cut -d# -f2 | sort -u); do grep -q \"id=\\\"\$a\\\"\" services.html || exit 1; done"
chk "llms.txt: no unproven claims (licensed, insured, years, ratings)" "! grep -iwE 'licensed|insured|bonded|years of experience|rated|stars' llms.txt | grep -viE \"don't state|none are claimed\""
chk "llms.txt stays invisible: no page links to it" "! grep -q 'llms.txt' $PAGES"
chk "home structured data parses and matches the site (phone, both areas, no street address)" "python3 -I -c 'import json,re,sys; s=open(\"index.html\").read(); b=re.findall(r\"<script type=\\\"application/ld\\+json\\\">(.*?)</script>\", s, re.S); assert len(b)==1; d=json.loads(b[0]); assert d[\"telephone\"]==\"+1-832-476-1941\" and d[\"email\"]==\"quotes@thespringcleaningcrew.com\"; a=json.dumps(d[\"areaServed\"]); assert \"Houston\" in a and \"The Woodlands\" in a; assert \"streetAddress\" not in b[0] and \"aggregateRating\" not in b[0] and \"review\" not in b[0].lower()'"
chk "structured data appears only on the home page" "[[ \$(grep -l 'application/ld+json' $PAGES | tr '\n' ' ') == 'index.html ' ]]"
chk "IndexNow: exactly one key file, named for the key it holds" "f=\$(ls | grep -E '^[0-9a-f]{32}\\.txt\$'); [[ \$(echo \"\$f\" | grep -c .) -eq 1 ]] && [[ \"\$(cat \$f)\" == \"\${f%.txt}\" ]]"
echo "passed $pass, failed $fail"
[[ $fail -eq 0 ]]
